  {
    "narration": "Câu thoại cảnh 1...",
    "audioDuration": 3.5,
    "searchKeyword": "galaxy space stars",
    "words": [
      { "word": "Câu", "start": 0.1, "end": 0.4 },
      { "word": "thoại", "start": 0.45, "end": 0.8 }
    ]
  }
